import{_ as s,C as i,c as a,o as l,aj as c,j as t,G as r,a as p,w as h}from"./chunks/framework.Bfdr4H5E.js";const g="/sk/images/Rejection-1-Higher.webp",d="/sk/images/Rejection-2-Higher.webp",m="/sk/images/Rejection-1-Lower.webp",u="/sk/images/Rejection-2-Lower.webp",R=JSON.parse('{"title":"Strong Rejection of Higher or Lower Prices","description":"","frontmatter":{"outline":"deep","prev":{"text":"Aggressive Initiation","link":"/trading-with-pav/aggressive-initiation"},"next":{"text":"Price Action the Complete Picture","link":"/trading-with-pav/price-action-the-complete-picture"}},"headers":[],"relativePath":"trading-with-pav/strong-rejection-of-higher-or-lower-prices.md","filePath":"trading-with-pav/strong-rejection-of-higher-or-lower-prices.md"}'),w={name:"trading-with-pav/strong-rejection-of-higher-or-lower-prices.md"};function f(b,e,v,j,y,_){const o=i("GraphComment"),n=i("ClientOnly");return l(),a("div",null,[e[0]||(e[0]=c('<h1 id="strong-rejection-of-higher-or-lower-prices" tabindex="-1">Strong Rejection of Higher or Lower Prices <a class="header-anchor" href="#strong-rejection-of-higher-or-lower-prices" aria-label="Permalink to &quot;Strong Rejection of Higher or Lower Prices&quot;">​</a></h1><p>In this article we going to learn about Strong Rejection of Higher or Lower Prices which concludes the Price Action Fundamentals.</p><ul><li><p>Strong rejection of either higher or lower price levels is a sudden price reversal.</p></li><li><p>This pattern is made when the price goes one way aggressively and then turns quickly and with the same aggression and speed goes the other way.</p></li><li><p>A classic example would be a type of candle called the “pin bar.” But pin bars aren’t the only visual form of strong rejection.</p></li><li><p>A common sign for all strong rejections is an aggression and sudden reversal.</p></li><li><p>What happens is that one side of the market (for example buyers) is aggressive and moves the price in one way.</p></li><li><p>Then it clashes with the other side (for example strong sellers) which suddenly becomes even stronger and even more aggressive.</p><ul><li>So the price turns quickly, and the stronger side takes over.</li></ul></li><li><p>The area where the other side took over is very significant because it marks a place where strong market participants aggressively rejected the current course of action and started a strong countermove.</p><ul><li>This place is significant for us because it will most likely be defended again if the price gets near again.</li></ul></li><li><p>It becomes a new support/resistance zone. (Which will learn later in this volume.)</p></li></ul><p>Below is a chart where will see rejection of higher price marked in second image</p><p><img src="'+g+'" alt="Rejection-1-Higher"></p><p><img src="'+d+'" alt="Rejection-2-Higher"></p><p>In above image rejection of higher prices is marked and in below image will see rejection of lower price marked in last image.</p><p><img src="'+m+'" alt="Rejection-1-Lower"></p><p><img src="'+u+'" alt="Rejection-2-Lower"></p><ul><li><p>As you can see, there doesn’t need to be a pin bar for us to <strong>spot aggressive rejection</strong>.</p></li><li><p>The only rule is that there needs to be a <strong>sudden reversal</strong>.</p></li><li><p><strong>Candle patterns don’t concern us. The reason for that is that they are different on different timeframes</strong>.</p></li><li><p>A <strong>strong rejection</strong> should be visible on more time-frames, not just one.</p></li><li><p><strong>Remember</strong>, we are analyzing the price “<strong>flow and aggression</strong>” not candle patterns.</p></li><li><p>It takes some time to be able to <strong>spot and recognize strong rejections</strong> and tell them from rejections that are not so significant.</p></li><li><p>But with practice and some time you will be able to do this, and</p><ul><li><strong>with a look on chart, be able read whole sentences instead of only separate letters.</strong></li></ul></li><li><p><strong>Remember</strong>, places where prices suddenly turned and changed direction are very significant.</p><ul><li><strong>We should always watch out for them in our price action analysis.</strong></li></ul></li></ul><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',11)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/gz17fVVDBwk",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[p("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),r(n,null,{default:h(()=>[r(o)]),_:1})])}const x=s(w,[["render",f]]);export{R as __pageData,x as default};
